  'land.docTitle': 'CM Reborn: il leggendario manageriale di calcio, gratis nel tuo browser',
  'land.nav.features': 'Caratteristiche', 'land.nav.screens': 'Screenshot', 'land.nav.ranking': 'Classifiche', 'land.nav.faq': 'FAQ',
