  'land.nav.join': 'Partecipa', 'land.join.kicker': 'Unisciti a noi', 'land.join.title': 'Vuoi far parte del progetto?', 'land.join.text': "CM Reborn è un progetto di appassionati e c'è sempre posto per altre mani. Scrivi qualche riga su di te e su come vorresti aiutare: ti risponderò.", 'land.join.b1': 'Sviluppatori, designer ed esperti di dati calcistici', 'land.join.b2': 'Tester che vogliono provare le novità prima di tutti', 'land.join.b3': 'Traduttori e chi vuole aiutare la community', 'land.join.name': 'Nome', 'land.join.email': 'E-mail', 'land.join.role': 'Come vorresti aiutare?', 'land.join.message': 'Raccontaci qualcosa di te', 'land.join.placeholder': 'Chi sei e cosa ti piacerebbe fare?', 'land.join.role.developer': 'Sviluppo', 'land.join.role.designer': 'Design e grafica', 'land.join.role.data': 'Dati e database', 'land.join.role.testing': 'Test e segnalazione bug', 'land.join.role.translation': 'Traduzione', 'land.join.role.community': 'Community e contenuti', 'land.join.role.other': 'Altro', 'land.join.send': 'Invia', 'land.join.sending': 'Invio in corso…', 'land.join.thanks': 'Grazie per averci contattato!', 'land.join.thanksText': 'Il tuo messaggio è stato ricevuto e ti risponderò via e-mail.', 'land.join.privacy': 'Il tuo nome e la tua e-mail vengono usati solo per risponderti.', 'land.join.offline': 'Il modulo funziona solo sulla versione principale del gioco.', 'land.join.goLive': 'Vai al modulo', 'land.join.err.email': 'Controlla il tuo indirizzo e-mail.', 'land.join.err.limit': 'Troppi messaggi: riprova più tardi.', 'land.join.err.missing': 'Inserisci il tuo nome e un messaggio di almeno 10 caratteri.', 'land.join.err.other': 'Qualcosa è andato storto: riprova.',
