  'land.s.matchday.kicker': 'Giornata', 'land.s.matchday.title': 'Segui ogni occasione', 'land.s.matchday.text': 'Segui la partita in diretta con telecronaca e statistiche, e capisci esattamente perché hai vinto o perso.',
  'land.s.matchday.b1': 'xG, mappe dei tiri, momentum e heatmap', 'land.s.matchday.b2': "L'analisi del tuo vice dopo ogni partita", 'land.s.matchday.b3': 'Metti in pausa, cambia tattica ed effettua sostituzioni da tastiera',
